'use strict';

// MODULES //

var resolve = require( '@stdlib/blas/base/layout-resolve-enum' );
var addon = require( './../src/addon.node' );


// MAIN //

/**
* Generates a double-precision floating-point Vandermonde matrix.
*
* @param {string} order - storage layout
* @param {NonNegativeInteger} M - number of rows in the matrix `Out`
* @param {NonNegativeInteger} N - number of columns in the matrix `Out`
* @param {number} mode - specifies whether columns should contain powers that are increasing (`1`) or decreasing (`-1`)
* @param {Float64Array} x - input vector
* @param {integer} strideX - stride length for `x`
* @param {Float64Array} out - output matrix
* @param {PositiveInteger} LDO - stride of the first dimension of `Out` (a.k.a., leading dimension of the matrix `Out`)
* @returns {Float64Array} output matrix
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var x = new Float64Array( [ 1.0, 2.0, 3.0 ] );
* var out = new Float64Array( 9 );
*
* dvander( 'row-major', 3, 3, -1, x, 1, out, 3 );
* // out => <Float64Array>[ 1.0, 1.0, 1.0, 4.0, 2.0, 1.0, 9.0, 3.0, 1.0 ]
*/
function dvander( order, M, N, mode, x, strideX, out, LDO ) {
	addon( resolve( order ), M, N, mode, x, strideX, out, LDO );
	return out;
}


// EXPORTS //

module.exports = dvander;
